using System;
using System.IO;
using System.Reflection;
using System.Windows;
using System.Windows.Media;
using System.Windows.Media.Imaging;
static class MediaVisualChecks {
 public static void Run(){
  var heightSettings=new System.Web.Script.Serialization.JavaScriptSerializer();if(new AppearanceSettings().mediaPlayerHeight!=100||heightSettings.Deserialize<AppearanceSettings>(heightSettings.Serialize(new AppearanceSettings{mediaPlayerHeight=150})).mediaPlayerHeight!=150||MediaCard.PlayerHeight(true,100)!=204||MediaCard.PlayerHeight(false,100)!=140||MediaCard.PlayerHeight(true,150)!=306||MediaCard.PlayerHeight(false,75)!=140||MediaCard.PlayerHeight(true,75)!=140)throw new Exception("Saved player height must preserve current defaults and keep controls visible");
  foreach(var screen in System.Windows.Forms.Screen.AllScreens){int rate=DisplayCadence.Refresh(screen.DeviceName);if(rate<2||rate>1000)throw new Exception("Invalid monitor refresh rate");Console.WriteLine("Display animation target: "+screen.DeviceName+" "+rate+" Hz");}
  var timing=DisplayCadence.At(new System.Windows.Controls.Border(),new System.Windows.Media.Animation.DoubleAnimation());if(System.Windows.Media.Animation.Timeline.GetDesiredFrameRate(timing)!=DisplayCadence.Rate(new System.Windows.Controls.Border()))throw new Exception("CC animation does not follow monitor refresh");
  foreach(int width in new[]{460,680}){
   var card=new MediaCard{Width=width,Height=204};card.Resources=(ResourceDictionary)System.Windows.Markup.XamlReader.Load(System.Xml.XmlReader.Create(Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"control-center-styles.xaml")));ControlCenterTheme.Current.Install(card.Resources);card.SetValue(System.Windows.Documents.TextElement.ForegroundProperty,ControlCenterTheme.Current.Brush("Text"));
   Func<string,object> field=name=>typeof(MediaCard).GetField(name,BindingFlags.NonPublic|BindingFlags.Instance).GetValue(card);
   var title=(System.Windows.Controls.TextBlock)field("title");var artist=(System.Windows.Controls.TextBlock)field("artist");var albumText=(System.Windows.Controls.TextBlock)field("albumText");var playlistText=(System.Windows.Controls.TextBlock)field("playlistText");title.Text="Dancing in the Dark";artist.Text="Artist: Mondo Loops";albumText.Text="Album: Nature's Beauty";playlistText.Text="Playlist: Lofi Study 2026";card.UpdateLinkButtons(true,new MediaLinks("song","playlist","album","https://open.spotify.com/artist/fixture"));
   card.Measure(new Size(width,204));card.Arrange(new Rect(0,0,width,204));card.UpdateLayout();
   if(Math.Abs(title.TranslatePoint(new Point(),card).X-artist.TranslatePoint(new Point(),card).X)>.1||title.FontSize<22||((System.Windows.Controls.Image)field("art")).Width<80||((System.Windows.Controls.Button)field("play")).ActualWidth<44)throw new Exception("Player hierarchy, metadata alignment or enlarged controls failed");
   var linkButtons=(System.Windows.Controls.Button[])field("linkButtons");if(linkButtons.Length!=4||linkButtons[1].Content!=title||linkButtons[2].Content!=playlistText||linkButtons[3].Content!=albumText||linkButtons[0].FontSize<13||!linkButtons[2].IsEnabled||Math.Abs(albumText.TranslatePoint(new Point(),card).X-title.TranslatePoint(new Point(),card).X)>.1)throw new Exception("Spotify song/playlist/album copy actions must be embedded in aligned text, with larger Copy all");
   var shuffle=(System.Windows.Controls.Button)field("shuffleButton");var play=(System.Windows.Controls.Button)field("play");var art=(System.Windows.Controls.Image)field("art");var copy=linkButtons[0];var artistButton=(System.Windows.Controls.Button)field("artistButton");if(artistButton.Content!=artist||!artistButton.IsEnabled||Math.Abs(copy.TranslatePoint(new Point(copy.ActualWidth/2,0),card).X-art.TranslatePoint(new Point(art.ActualWidth/2,0),card).X)>.1||copy.TranslatePoint(new Point(),card).Y<art.TranslatePoint(new Point(0,art.ActualHeight),card).Y||Math.Abs(shuffle.TranslatePoint(new Point(0,shuffle.ActualHeight/2),card).Y-play.TranslatePoint(new Point(0,play.ActualHeight/2),card).Y)>.1)throw new Exception("Artwork copy centering, artist action or shuffle row alignment failed");
   var player=new RenderTargetBitmap(width,204,96,96,PixelFormats.Pbgra32);player.Render(card);var playerPng=new PngBitmapEncoder();playerPng.Frames.Add(BitmapFrame.Create(player));using(var file=File.Create(Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"media-player-layout-"+width+".png")))playerPng.Save(file);
   card.Height=MediaCard.PlayerHeight(true,75);card.Measure(new Size(width,card.Height));card.Arrange(new Rect(0,0,width,card.Height+12));card.UpdateLayout();double topGap=((FrameworkElement)art.Parent).TranslatePoint(new Point(),card).Y,bottomGap=card.ActualHeight-copy.TranslatePoint(new Point(0,copy.ActualHeight),card).Y;if(Math.Abs(topGap-bottomGap)>.1)throw new Exception("Minimum media player padding must be symmetric: "+topGap+" / "+bottomGap);var minPlayer=new RenderTargetBitmap(width,(int)Math.Ceiling(card.ActualHeight),96,96,PixelFormats.Pbgra32);minPlayer.Render(card);var minPng=new PngBitmapEncoder();minPng.Frames.Add(BitmapFrame.Create(minPlayer));using(var minFile=File.Create(Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"media-player-minimum-"+width+".png")))minPng.Save(minFile);
   var visual=new MediaAtmosphere{Width=width,Height=180};
   typeof(MediaAtmosphere).GetField("level",BindingFlags.NonPublic|BindingFlags.Instance).SetValue(visual,.8);
   typeof(MediaAtmosphere).GetField("phase",BindingFlags.NonPublic|BindingFlags.Instance).SetValue(visual,2.4);
   visual.Measure(new Size(width,180));visual.Arrange(new Rect(0,0,width,180));visual.UpdateLayout();
   var bitmap=new RenderTargetBitmap(width,180,96,96,PixelFormats.Pbgra32);bitmap.Render(visual);var pixels=new byte[width*180*4];bitmap.CopyPixels(pixels,width*4,0);if(pixels[(90*width+width/2)*4+3]==0)throw new Exception("Media landscape did not render");var encoder=new PngBitmapEncoder();encoder.Frames.Add(BitmapFrame.Create(bitmap));using(var file=File.Create(Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"media-aurora-"+width+".png")))encoder.Save(file);
  }
  if(MediaAtmosphere.Response(.001,.08,200)<=MediaAtmosphere.Response(.001,.08,100)||MediaAtmosphere.Response(0,.08,400)!=0)throw new Exception("Ribbon sensitivity must amplify quiet sound and preserve silence");
  for(int layer=0;layer<3;layer++)for(int i=0;i<=100;i++){double y=MediaAtmosphere.Ribbon(i/100.0,20,layer,1);if(Double.IsNaN(y)||Double.IsInfinity(y)||Math.Abs(y)>1.1)throw new Exception("Unbounded aurora ribbon geometry");}
  Console.WriteLine("PASS: themed aurora media landscape renders at narrow/wide CC sizes; bounded ribbon geometry. Synthetic amplitude only, no audio devices opened.");
 }
}
